/* br_globals.c: the one definition of each original global (generated by
 * ports/brally/tools/unify.py). Initial values: the data lift. */
/* A global with the original's extent (tools/globext.py): the declared
 * object at offset 0 and the bytes up to the next address the original
 * names, under the global's own linker symbol -- code that walks past the
 * declared type, as the original does, stays inside it. */
#define BR_SYM_STR2(x) #x
#define BR_SYM_STR(x) BR_SYM_STR2(x)
#define BR_GLOBAL_EXTENT(T, name, dims, pad) \
    struct { T v dims; unsigned char extent[pad]; } name##__extent \
        __asm__(BR_SYM_STR(__USER_LABEL_PREFIX__) #name)
/* A run of neighbouring globals laid out as the original lays them out
 * (tools/globfold.py): one block of storage holding the original's bytes
 * from the 64-byte boundary below its first global, and each global a
 * linker symbol at its original offset in it, so code that reaches from one
 * into the next reaches what the original reached. On Mach-O each name is
 * an alternate entry into the block, which keeps the linker from splitting
 * it at the names. */
#define BR_ALIGN64 __attribute__((aligned(64), nocommon))
#if defined(__APPLE__)
#define BR_BLOCK_ALT(name) ".alt_entry " BR_SYM_STR(__USER_LABEL_PREFIX__) #name "\n"
#else
#define BR_BLOCK_ALT(name) ""
#endif
#define BR_BLOCK(blk, head, len) \
    BR_ALIGN64 unsigned char br_block_##blk[head + len]; \
    extern unsigned char br_blockdata_##blk[len]; \
    BR_BLOCK_AT(blk, br_blockdata_##blk, head)
#define BR_BLOCK_AT(blk, name, off) \
    __asm__(".globl " BR_SYM_STR(__USER_LABEL_PREFIX__) #name "\n" BR_BLOCK_ALT(name) \
            BR_SYM_STR(__USER_LABEL_PREFIX__) #name " = " \
            BR_SYM_STR(__USER_LABEL_PREFIX__) "br_block_" #blk " + " #off "\n")

